<?php require __DIR__.'/includes/auth.php';$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){admin_verify_csrf();if($_POST['act']==='save'){$path=admin_upload('image','gallery');$p->prepare('INSERT INTO gallery(title,image_path,alt_text,category,sort_order,status) VALUES(?,?,?,?,?,?)')->execute([$_POST['title'], $path,$_POST['alt_text'],$_POST['category'],(int)$_POST['sort_order'],isset($_POST['status'])?(int)$_POST['status']:1]);header('Location: gallery.php');exit;}if($_POST['act']==='delete'){$q=$p->prepare('SELECT image_path FROM gallery WHERE id=?');$q->execute([(int)$_POST['id']]);admin_delete_image($q->fetchColumn());$p->prepare('DELETE FROM gallery WHERE id=?')->execute([(int)$_POST['id']]);header('Location: gallery.php');exit;}}$rows=$p->query('SELECT * FROM gallery ORDER BY sort_order,id DESC')->fetchAll();$page_title='Gallery';require __DIR__.'/includes/header.php';?><div class="form"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=admin_csrf()?>"><input type="hidden" name="act" value="save"><div class="formgrid"><div class="field"><label>Image</label><input required type="file" name="image" accept="image/jpeg,image/png,image/webp"></div><div class="field"><label>Title</label><input name="title"></div><div class="field"><label>Alt Text</label><input name="alt_text"></div><div class="field"><label>Category</label><input name="category" placeholder="ATV, Rafting, Swing..."></div><div class="field"><label>Sort Order</label><input type="number" name="sort_order" value="0"></div></div><div class="actions"><button class="btn">Upload</button></div></form></div><div class="section tablebox"><table class="table"><tr><th>Image</th><th>Title</th><th>Category</th><th></th></tr><?php foreach($rows as $r):?><tr><td><img class="thumb" src="../<?=admin_e($r['image_path'])?>"></td><td><?=admin_e($r['title'])?><br><span class="small"><?=admin_e($r['alt_text'])?></span></td><td><?=admin_e($r['category'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=admin_csrf()?>"><input type="hidden" name="act" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn red" data-confirm="Delete image?">Delete</button></form></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/includes/footer.php';?>